const COLORS=['#ffe34d','#ff8055','#74b7ff','#a4ed8a','#cda0ff','#ff4055','#4767dc','#ff8fdb','#48db72','#287a53','#3c4354','#f4f5ff'];
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v);},mix=(a,b,t)=>a+(b-a)*clamp(t);
const circle=(c,x,y,r,color,stroke='#101a2c',w=5)=>{c.fillStyle=color;c.beginPath();c.arc(x,y,Math.max(0,r),0,Math.PI*2);c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke();}};
function path(c,points,color,width=8){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle=color;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.stroke();}
function limb(c,points,color,width=14){path(c,points,'#101a2c',width+7);path(c,points,color,width);}
function polygon(c,points,color,stroke='#101a2c',w=5){c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();if(stroke){c.lineWidth=w;c.strokeStyle=stroke;c.stroke();}}
function ellipse(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,Math.max(0,rx),Math.max(0,ry),0,0,Math.PI*2);c.fill();}
function star(c,x,y,r,color,rotation=0){c.save();c.translate(x,y);c.rotate(rotation);const pts=[];for(let i=0;i<12;i++){const a=i*Math.PI/6,s=i%2?r*.4:r;pts.push([Math.cos(a)*s,Math.sin(a)*s]);}polygon(c,pts,color,null);c.restore();}
function burst(c,x,y,t,color='#ffe8a0',label=''){if(t<0||t>.6)return;const p=t/.6;c.save();c.globalAlpha=1-p;for(let i=0;i<14;i++){const a=i*2.4;path(c,[[x+Math.cos(a)*p*30,y+Math.sin(a)*p*30],[x+Math.cos(a)*(30+p*90),y+Math.sin(a)*(30+p*90)]],i%2?color:'#fff4d7',6*(1-p));}star(c,x,y,30+50*p,color,p);if(label){c.translate(x,y-65-p*30);c.rotate(-.12);c.font='900 46px Impact,Arial';c.textAlign='center';c.lineWidth=7;c.strokeStyle='#101a2c';c.strokeText(label,0,0);c.fillStyle='#fff0bd';c.fillText(label,0,0);}c.restore();}
function sparks(c,x,y,t,n=20,colors=['#ffe34d','#ff8055','#fff0bd']){for(let i=0;i<n;i++){const p=((t*1.1+i*.073)%1+1)%1,a=i*2.399,r=15+p*90;c.save();c.globalAlpha=(1-p)*.8;star(c,x+Math.cos(a)*r,y+Math.sin(a)*r-p*20,2+(1-p)*5,colors[i%colors.length],p*3);c.restore();}}
function hero(c,type,x,y,{pose='ready',phase=0,face=1,scale=1,lean=0,alpha=1}={}){const color=COLORS[type],walk=Math.sin(phase*12),stride=pose==='run'?walk*28:pose==='air'?20:4;
 ellipse(c,x,y+6,48*scale,10*scale,'#07122245');c.save();c.translate(x,y);c.scale(face*scale,scale);c.rotate(lean);c.globalAlpha=alpha;
 // Heavy outlines, colored clothes, gloves, and expressive faces make the cast read as cartoons.
 limb(c,[[-10,-67],[-24+stride,-35],[-34-stride*.4,0]],'#223047',19);limb(c,[[10,-67],[26-stride,-32],[38+stride*.4,0]],'#29394f',19);
 ellipse(c,-34-stride*.4,0,22,10,'#f0e9d9');ellipse(c,38+stride*.4,0,23,10,color);path(c,[[-53-stride*.4,5],[-16-stride*.4,5]],'#101a2c',5);path(c,[[20+stride*.4,6],[59+stride*.4,6]],'#101a2c',5);
 polygon(c,[[-20,-130],[18,-130],[30,-103],[20,-62],[-22,-62],[-30,-100]],color);path(c,[[-15,-116],[-8,-107],[0,-117],[9,-108],[18,-118]],'#ffffff60',3);path(c,[[0,-101],[0,-69]],'#101a2c44',3);path(c,[[-17,-72],[17,-72]],'#101a2c55',5);
 let front=[[15,-120],[38,-98],[57,-117]],back=[[-15,-119],[-35,-95],[-19,-86]];
 if(pose==='run'){front=[[15,-120],[32+walk*16,-104],[48+walk*24,-125]];back=[[-15,-119],[-34-walk*12,-97],[-16-walk*18,-80]];}
 if(pose==='punch'){front=[[15,-120],[55,-128],[101,-133]];back=[[-15,-119],[14,-106],[33,-137]];}
 if(pose==='guard'){front=[[15,-120],[45,-140],[43,-166]];back=[[-15,-119],[6,-145],[22,-158]];}
 if(pose==='uppercut'){front=[[15,-120],[48,-146],[57,-211]];back=[[-15,-119],[-28,-106],[-4,-92]];}
 if(pose==='cast'){front=[[15,-120],[48,-120],[78,-134]];back=[[-15,-119],[-40,-130],[-47,-166]];}
 if(pose==='sword'){front=[[15,-120],[48,-151],[55,-183]];back=[[-15,-119],[-28,-96],[-2,-85]];}
 if(pose==='climb'){front=[[15,-120],[31,-153],[35,-185]];back=[[-15,-119],[-29,-143],[-28,-176]];}
 if(pose==='air'){front=[[15,-120],[37,-134],[55,-155]];back=[[-15,-119],[-45,-129],[-63,-148]];}
 limb(c,back,color,13);circle(c,...back[2],13,color);limb(c,front,color,15);circle(c,...front[2],15,color);ellipse(c,front[2][0]-3,front[2][1]-5,6,3,'#ffffff80');
 circle(c,0,-164,31,'#f3e8ce');c.save();c.beginPath();c.arc(0,-164,30,0,Math.PI*2);c.clip();c.fillStyle=color;c.fillRect(-34,-199,68,24);c.fillStyle='#ffffff30';c.fillRect(-26,-193,45,5);c.restore();path(c,[[-26,-176],[26,-176]],'#101a2c',4);
 c.fillStyle='#101a2c';c.beginPath();c.ellipse(8,-163,4.5,7,0,0,Math.PI*2);c.ellipse(23,-161,3.5,6,0,0,Math.PI*2);c.fill();path(c,[[2,-174],[13,-170]],'#101a2c',4);path(c,[[18,-170],[28,-172]],'#101a2c',3);
 if(pose==='inhale'){ellipse(c,20,-145,10,12,'#14203b');}else{path(c,[[10,-145],[23,-143],[27,-148]],'#101a2c',3);}
 if(type===5){c.save();const hand=front[2];c.translate(hand[0],hand[1]);c.rotate(pose==='sword'?.9:0);c.shadowColor='#ff7b3c';c.shadowBlur=22;polygon(c,[[0,0],[9,-106],[19,-137],[29,-106],[31,0]],'#ff5e39','#722434',4);polygon(c,[[12,-3],[18,-104],[23,-122],[25,-3]],'#fff0a0',null);path(c,[[-8,4],[37,4]],'#ffe590',9);c.restore();}
 if(type===11){path(c,[[front[2][0]-8,front[2][1]+7],[front[2][0]+7,front[2][1]+7]],'#e5c66c',4);}
 c.restore();}
function dog(c,x,y,t,{type=9,face=1,scale=1,charge=0,zombie=false}={}){const color=type===9?'#2e9169':'#65c96c',step=Math.sin(t*15)*16;ellipse(c,x,y+5,70*scale,12*scale,'#07122250');c.save();c.translate(x,y);c.scale(face*scale,scale);for(const [px,k]of [[-50,1],[-25,-1],[30,-1],[56,1]])limb(c,[[px,-59],[px+k*step*.5,-27],[px-k*step,0]],color,17);ellipse(c,0,-78,70,37,color);c.strokeStyle='#102b2c';c.lineWidth=5;c.stroke();path(c,[[-62,-83],[-88,-112],[-96,-140]],color,18);if(type===9){polygon(c,[[-56,-105],[-58,-139],[-32,-112],[-20,-151],[3,-113],[19,-145],[35,-109]],'#a3fff1','#15524f',4);}
 polygon(c,[[32,-83],[38,-151],[85,-161],[120,-126],[112,-85],[68,-75]],color);polygon(c,[[40,-150],[23,-184],[64,-163]],color);polygon(c,[[85,-158],[112,-183],[111,-137]],color);c.fillStyle=zombie?'#ff786a':'#f6eec8';c.beginPath();c.ellipse(86,-133,15,17,.1,0,Math.PI*2);c.fill();circle(c,93,-133,6,zombie?'#b52330':'#142b30',null);ellipse(c,117,-118,13,10,'#142b30');path(c,[[75,-97],[110,-99]],'#15383a',7);for(let i=0;i<3;i++)polygon(c,[[78+i*12,-98],[83+i*12,-85],[88+i*12,-99]],'#fff0d1',null);if(charge>0){c.shadowBlur=35;c.shadowColor='#7affee';circle(c,124,-111,12+charge*20,'#b8fff3',null);c.shadowBlur=0;}c.restore();}
function unicorn(c,x,y,t,face=1){ellipse(c,x,y+6,68,12,'#07122240');c.save();c.translate(x,y);c.scale(face,1);const step=Math.sin(t*16)*15;for(const [px,k]of [[-43,1],[-20,-1],[28,-1],[47,1]])limb(c,[[px,-52],[px+k*step,-25],[px-k*step,0]],'#fff0fd',13);ellipse(c,0,-75,65,30,'#fff0fd');c.strokeStyle='#9f6ba6';c.lineWidth=4;c.stroke();limb(c,[[35,-76],[48,-133]],'#fff0fd',26);ellipse(c,67,-141,35,22,'#fff0fd');c.stroke();polygon(c,[[52,-157],[58,-210],[74,-160]],'#ffe89b','#9f6ba6',3);path(c,[[37,-152],[20,-125],[29,-94]],'#ff8fdb',15);path(c,[[-61,-80],[-95,-80],[-117,-59]],'#ff8fdb',14);path(c,[[-65,-77],[-99,-64],[-113,-44]],'#bda0ff',9);circle(c,78,-146,5,'#15314a',null);c.restore();sparks(c,x-face*115,y-60,t,22,['#ff8fdb','#ffe34d','#a4ed8a','#74b7ff']);}
function portal(c,x,y,t,alpha=1){c.save();c.globalAlpha=alpha;c.strokeStyle='#d8b5ff';c.lineWidth=10;c.shadowColor='#b879ff';c.shadowBlur=30;c.beginPath();c.ellipse(x,y-115,55+Math.sin(t*15)*3,125,0,0,Math.PI*2);c.stroke();c.lineWidth=3;c.strokeStyle='#fff1ff';c.stroke();c.restore();}
function vine(c,x,bottom,height,t){path(c,[[x,bottom],[x-15,bottom-height*.3],[x+12,bottom-height*.6],[x,bottom-height]],'#244a40',15);path(c,[[x,bottom],[x-15,bottom-height*.3],[x+12,bottom-height*.6],[x,bottom-height]],'#9ee591',8);for(let y=bottom-30;y>bottom-height;y-=42){const side=Math.floor(y/42)%2?1:-1;c.save();c.translate(x+side*19,y);c.rotate(side*.5);ellipse(c,0,0,23,10,'#9ee591');c.restore();}}
function beam(c,x,y,endX,endY,t){c.save();c.shadowColor='#66ffe8';c.shadowBlur=35;path(c,[[x,y],[endX,endY]],'#1d7794',52);path(c,[[x,y],[endX,endY]],'#6dffe5',30);path(c,[[x,y],[endX,endY]],'#eeffcf',12);for(let i=0;i<12;i++){const p=(i/12+t*2)%1;ellipse(c,mix(x,endX,p),mix(y,endY,p),12,22,'#b8fff3');}c.restore();}
function background(c,scene,t){const skies=[['#153b59','#79b5b1'],['#1d254c','#b35d69'],['#3974a9','#b4dcdf'],['#2a1c38','#bc6041'],['#314f63','#d2ac9a'],['#16243c','#536b81']];const g=c.createLinearGradient(0,0,0,720);g.addColorStop(0,skies[scene][0]);g.addColorStop(1,skies[scene][1]);c.fillStyle=g;c.fillRect(0,0,1280,720);ellipse(c,1040,150,80,80,scene===1?'#f6dfbd':'#ffe2a866');
 for(let layer=0;layer<3;layer++){const pts=[[0,700]];for(let x=0;x<=1350;x+=90)pts.push([x,370+layer*85+Math.sin(x*.006+layer)*55]);pts.push([1350,720]);polygon(c,pts,['#243e5466','#23435188','#243d4aaa'][layer],null);}
 if(scene===0){polygon(c,[[205,430],[490,430],[460,470],[310,495],[220,470]],'#415866');path(c,[[205,430],[490,430]],'#b6d69a',12);}
 if(scene===1){for(let i=0;i<13;i++){const x=i*112-30,y=270+(i*73)%180;c.fillStyle='#252c49';c.fillRect(x,y,82,380);for(let row=0;row<6;row++)for(let col=0;col<2;col++){c.fillStyle=(i+row)%2?'#97dbd155':'#ffc1a355';c.fillRect(x+14+col*32,y+18+row*40,13,19);}}}
 if(scene===2){for(let i=0;i<12;i++)for(let k=0;k<3;k++)ellipse(c,(i*173+t*7)%1450-80+k*22,160+(i*59)%360,45,22,'#f4fbff44');polygon(c,[[150,445],[500,445],[460,495],[310,525],[190,480]],'#829ba0');path(c,[[150,445],[500,445]],'#d8f1d3',13);}
 if(scene===3){polygon(c,[[500,620],[760,190],[840,195],[1170,620]],'#442d42');path(c,[[775,215],[790,320],[840,370],[829,465],[900,590]],'#f18a53',18);c.fillStyle='#e67742';c.fillRect(0,636,1280,84);for(let i=0;i<30;i++)ellipse(c,(i*67+t*20)%1380,650+Math.sin(i+t*2)*7,24,5,'#ffd178');}
 c.fillStyle=scene===3?'#403645':'#334956';c.fillRect(0,610,1280,100);c.fillStyle=scene===3?'#d88759':scene===1?'#96e8df':'#b6cc98';c.fillRect(0,610,1280,10);for(let i=0;i<32;i++){c.fillStyle=i%2?'#152d3c44':'#f4ead90b';c.fillRect(i*42+1,628,39,30);}
 // Inked foreground rocks ground the action.
 polygon(c,[[-20,720],[0,655],[60,640],[108,674],[159,720]],'#172e3e');polygon(c,[[1125,720],[1160,670],[1220,647],[1300,676],[1300,720]],'#172e3e');}
export function cinematicState(ms){const elapsed=clamp(ms,0,CINEMATIC_DURATION-1),index=CINEMATIC_SCENES.findIndex(s=>elapsed<s.end),scene=CINEMATIC_SCENES[index];return {index,scene,local:(elapsed-scene.start)/1000,progress:clamp(ms/CINEMATIC_DURATION),finished:ms>=CINEMATIC_DURATION};}
export function drawCinematic(c,width,height,ms){const state=cinematicState(ms),q=state.local;c.save();c.fillStyle='#0a1020';c.fillRect(0,0,width,height);const s=Math.min(width/1280,height/720),left=(width-1280*s)/2,top=(height-720*s)/2;c.translate(left,top);c.scale(s,s);background(c,state.index,q);
 if(state.index===0){const rush=ease((q-.25)/1.05),vx=mix(200,830,rush),bounce=clamp((q-1.4)/1.3);if(q<1.45){for(let i=4;i>0;i--)hero(c,0,vx-i*38,610,{pose:'run',phase:q,alpha:.09+i*.025});hero(c,0,vx,610,{pose:'run',phase:q,lean:.13});}else hero(c,0,mix(830,590,bounce),610-Math.sin(bounce*Math.PI)*210,{pose:'air',phase:q,lean:-.2});hero(c,2,965,610,{pose:'guard',phase:q,face:-1});if(q>.8){c.save();c.globalAlpha=Math.min(1,(q-.8)*4);c.fillStyle='#8adfff33';c.strokeStyle='#bcf7ff';c.lineWidth=8;c.shadowColor='#92eaff';c.shadowBlur=25;c.beginPath();c.ellipse(900,485,82,135,-.12,0,Math.PI*2);c.fill();c.stroke();c.restore();}burst(c,875,490,q-1.32,'#b9f7ff','CLANG!');hero(c,1,335,430,{pose:'cast',scale:.75,phase:q});if(q>1.6){for(let i=-2;i<=2;i++){const f=((q-1.6)*1.3+i*.12)%1;const x=400+f*580,y=325+f*95+i*35;ellipse(c,x,y,18,10,'#ff7842');ellipse(c,x-6,y,9,5,'#fff1a0');}}}
 if(state.index===1){const charge=ease(q/.85),bx=mix(250,610,charge),ix=mix(965,760,ease(q/.85));hero(c,5,bx,610-(q>2?Math.sin(clamp((q-2)/1.1)*Math.PI)*220:0),{pose:'sword',phase:q,lean:q>2?-.6:0});hero(c,11,q>1.55?mix(ix,700,ease((q-1.55)/.5)):ix,610,{pose:q<1.5?'guard':q<2?'punch':'uppercut',phase:q,face:-1,lean:q>2?.12:0});if(q>.6&&q<1.45){c.strokeStyle='#ffb768';c.lineWidth=14;c.shadowColor='#ff7c4f';c.shadowBlur=20;c.beginPath();c.arc(690,420,125,-1.9,.75);c.stroke();c.shadowBlur=0;}burst(c,720,440,q-.9,'#ffe5bd','NOPE!');burst(c,650,435,q-2.05,'#f0f7ff','KAPOW!');sparks(c,700,430,q,12);}
 if(state.index===2){const growth=ease(q/.8);vine(c,340,610,growth*360,q);vine(c,425,610,growth*280,q);hero(c,3,365,610-ease((q-.5)/1.4)*250,{pose:'climb',phase:q,scale:.9});const blink=ease((q-.8)/.3),nx=q<1?940:570,ny=q<1?610:450;portal(c,940,610,q,1-blink*.8);portal(c,570,450,q,blink);hero(c,4,nx,ny,{pose:'cast',phase:q,alpha:q>.8&&q<1.12?.25:1,face:-1,scale:.9});hero(c,q>2.8?4:6,1090,610,{pose:q>1.6?'inhale':'ready',face:-1,phase:q,scale:.9});if(q>1.6){for(let i=0;i<18;i++){const p=((q-1.6)*1.6+i/18)%1,x=mix(620,1050,p),y=mix(340,460,p)+Math.sin(i*2)*60*(1-p);path(c,[[x-22,y-5],[x,y]],'#cddcff99',3);}if(q>2.65){portal(c,1090,610,q);burst(c,1085,420,q-2.8,'#d0b6ff','COPIED!');}}}
 if(state.index===3){dog(c,340+ease(q/.8)*100,610,q,{charge:q>1?clamp((q-1)/.7):0});const evade=ease((q-2)/1.2);hero(c,10,960+Math.sin(evade*Math.PI)*115,610-Math.sin(evade*Math.PI)*230,{pose:'cast',phase:q,face:-1,lean:evade*.5});if(q>.5&&q<2){const fog=c.createRadialGradient(960,470,15,960,470,235);fog.addColorStop(0,'#04071388');fog.addColorStop(1,'#04071300');c.fillStyle=fog;c.fillRect(690,220,540,450);circle(c,978,452,4,'#f0edf9',null);circle(c,996,452,4,'#f0edf9',null);}if(q>1.8&&q<3.2){beam(c,570,500,1180,470,q);sparks(c,1180,470,q,28,['#70ffe4','#fff0bd','#8ccaff']);}burst(c,1170,480,q-2,'#a1ffee','BOOOOM!');}
 if(state.index===4){const run=ease(q/2.8);hero(c,7,q<.9?mix(220,740,ease(q/.9)):mix(740,350,ease((q-.9)/1.5)),610-Math.sin(clamp((q-.9)/1.3)*Math.PI)*90,{pose:q<.9?'run':q<2.2?'air':'cast',phase:q,scale:.9});if(q<.9)hero(c,0,800,610,{pose:'guard',face:-1,scale:.8,phase:q});else unicorn(c,800+Math.sin(q*2)*90,610-Math.abs(Math.sin(q*5))*14,q);sparks(c,650,455,q,28,['#ff8fdb','#ffe34d','#b8a6ff']);dog(c,1120-550*Math.sin(clamp(q/3)*Math.PI),610,q,{type:8,face:-1,scale:.8});if(q<1.5)hero(c,1,530,610,{pose:'run',phase:q,scale:.7});else dog(c,475-Math.sin(q*2)*60,610,q,{type:8,scale:.7,zombie:true});burst(c,720,440,q-.9,'#ffa0e4','POOF!');burst(c,530,470,q-1.5,'#b9ef8d','WOOF!');}
 if(state.index===5){const arrive=ease(q/1.1);for(let i=0;i<12;i++){const x=105+i*97,y=665-(1-arrive)*(90+Math.sin(i*2)*50);if(i===8||i===9)dog(c,x,y,q,{type:i,scale:.46,face:i>5?-1:1});else hero(c,i,x,y,{pose:q<1?'air':'ready',phase:q,scale:.53,face:i>5?-1:1});}c.save();c.textAlign='center';c.font='900 96px Impact,Arial';c.lineWidth=13;c.strokeStyle='#142033';c.strokeText('STICKMAN',640,300);c.fillStyle='#fff0ce';c.fillText('STICKMAN',640,300);c.font='900 112px Impact,Arial';c.strokeText('SMASH ROYALE',640,410);c.fillStyle='#ff9b67';c.fillText('SMASH ROYALE',640,410);c.font='700 24px Arial';c.fillStyle='#d8e9ee';c.fillText('FIVE FIGHTERS ENTER. ONE FIGHTER WINS.',640,470);c.restore();for(let i=0;i<24;i++)star(c,(i*173)%1280,(q*65+i*67)%650,3+i%3,['#ffe3a0','#9ee4df','#ff9eb8'][i%3],q+i);}
 // Subtle letterboxing and a single soft cut, never full-screen strobing.
 c.fillStyle='#09111dee';c.fillRect(0,0,1280,34);c.fillRect(0,686,1280,34);const cut=Math.max(0,1-q/.12);if(cut>0){c.fillStyle=`rgba(6,11,21,${cut})`;c.fillRect(0,0,1280,720);}c.restore();return state;}
